[{"order":1,"type":"heading","text":"Standard Tokenomics & Interfaces: ERC-20, ERC-721, ERC-1155"},{"order":2,"type":"paragraph","text":"In the Ethereum ecosystem, token standards define how smart contracts interact, transfer value, and represent assets. Understanding the specifications of ERC-20, ERC-721, and ERC-1155 is fundamental for any Web3 developer building decentralized applications."},{"order":3,"type":"heading","text":"1. ERC-20: The Fungible Token Standard"},{"order":4,"type":"paragraph","text":"ERC-20 is the technical standard for fungible tokens on Ethereum. Fungibility means that each token is identical in type and value to another; 1 token A is always equal to 1 token B. Common use cases include governance tokens, utility tokens, and stablecoins."},{"order":5,"type":"subheading","text":"Core ERC-20 Interface"},{"order":6,"type":"code","text":"interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}"},{"order":7,"type":"heading","text":"2. ERC-721: The Non-Fungible Token Standard"},{"order":8,"type":"paragraph","text":"ERC-721 introduces non-fungibility, where every token has a unique identifier (tokenId) and distinct properties. This standard is widely used for digital art, collectibles, real estate deeds, and in-game items."},{"order":9,"type":"subheading","text":"Core ERC-721 Interface"},{"order":10,"type":"code","text":"interface IERC721 {
    function balanceOf(address owner) external view returns (uint256 balance);
    function ownerOf(uint256 tokenId) external view returns (address owner);
    function safeTransferFrom(address from, address to, uint256 tokenId, bytes calldata data) external;
    function transferFrom(address from, address to, uint256 tokenId) external;
    function approve(address to, uint256 tokenId) external;
    function getApproved(uint256 tokenId) external view returns (address operator);
    function setApprovalForAll(address operator, bool approved) external;
    function isApprovedForAll(address owner, address operator) external view returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
}"},{"order":11,"type":"heading","text":"3. ERC-1155: The Multi-Token Standard"},{"order":12,"type":"paragraph","text":"ERC-1155 combines the concepts of fungible (ERC-20) and non-fungible (ERC-721) tokens into a single smart contract. A single contract can contain any combination of fungible tokens, non-fungible tokens, or semi-fungible tokens. It also introduces batch operations, reducing gas costs significantly."},{"order":13,"type":"subheading","text":"Core ERC-1155 Interface"},{"order":14,"type":"code","text":"interface IERC1155 {
    function balanceOf(address account, uint256 id) external view returns (uint256);
    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids) external view returns (uint256[] memory);
    function setApprovalForAll(address operator, bool approved) external;
    function isApprovedForAll(address account, address operator) external view returns (bool);
    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes calldata data) external;
    function safeBatchTransferFrom(address from, address to, uint256[] calldata ids, uint256[] calldata amounts, bytes calldata data) external;

    event TransferSingle(address indexed operator, address indexed from, address indexed to, uint256 id, uint256 value);
    event TransferBatch(address indexed operator, address indexed from, address indexed to, uint256[] ids, uint256[] values);
    event ApprovalForAll(address indexed account, address indexed operator, bool approved);
    event URI(string value, uint256 indexed id);
}"},{"order":15,"type":"heading","text":"Summary of Differences"},{"order":16,"type":"bullet_point","text":"ERC-20: Best for currencies, voting power, and assets where units are interchangeable."},{"order":17,"type":"bullet_point","text":"ERC-721: Best for unique digital assets, identity, and items requiring individual tracking."},{"order":18,"type":"bullet_point","text":"ERC-1155: Best for gaming economies, mixed asset portfolios, and batch minting/transfers to save gas."}]
